PRAGMA foreign_keys = ON;

BEGIN;
CREATE TABLE action_jobs (
          id TEXT PRIMARY KEY,
          project_id TEXT NOT NULL,
          lane_generation INTEGER NOT NULL DEFAULT 1,
          job_kind TEXT NOT NULL DEFAULT 'github_issue' CHECK(job_kind IN ('github_issue', 'local_prompt', 'pull_request_review')),
          issue_id INTEGER,
          issue_title TEXT NOT NULL,
          issue_snapshot_json TEXT NOT NULL DEFAULT '{}',
          verification_report_json TEXT NOT NULL DEFAULT '',
          status TEXT NOT NULL CHECK(status IN (
            'queued', 'running', 'verifying', 'reviewing', 'waiting_merge', 'completed', 'failed', 'blocked', 'cancelled'
          )),
          branch TEXT,
          base_sha TEXT,
          head_sha TEXT,
          developer_profile_id TEXT,
          reviewer_profile_ids_json TEXT NOT NULL DEFAULT '[]',
          current_step TEXT,
          steps_json TEXT NOT NULL DEFAULT '[]',
          review_verdicts_json TEXT NOT NULL DEFAULT '[]',
          attempts_json TEXT NOT NULL DEFAULT '[]',
          pr_number INTEGER,
          pr_url TEXT,
          error_message TEXT,
          rework_count INTEGER NOT NULL DEFAULT 0,
          blocked_at INTEGER,
          auth_user_id TEXT,
          chat_session_id TEXT,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL
        , superseded_at INTEGER, superseded_by_job_id TEXT);

CREATE TABLE compaction_snapshots (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          workspace_id TEXT NOT NULL,
          session_id TEXT NOT NULL,
          created_at INTEGER NOT NULL,
          trigger TEXT NOT NULL CHECK(trigger IN ('soft','hard','manual')),
          tokens_before INTEGER,
          tokens_after INTEGER,
          content TEXT NOT NULL,
          truncated TEXT NOT NULL
        );

CREATE TABLE global_rule_audit_log (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          rule_id TEXT NOT NULL,
          action TEXT NOT NULL,
          before_json TEXT,
          after_json TEXT,
          actor TEXT,
          ts INTEGER NOT NULL
        );

CREATE TABLE global_rules (
          id TEXT PRIMARY KEY,
          title TEXT NOT NULL,
          body TEXT NOT NULL,
          category TEXT NOT NULL,
          severity TEXT NOT NULL,
          enabled INTEGER NOT NULL DEFAULT 1,
          priority INTEGER NOT NULL DEFAULT 100,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL,
          updated_by TEXT,
          match_json TEXT
        );

CREATE TABLE history_entries (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          namespace TEXT NOT NULL,
          session_id TEXT NOT NULL,
          role TEXT NOT NULL,
          text TEXT NOT NULL,
          ts INTEGER NOT NULL,
          kind TEXT
        );

CREATE TABLE history_session_links (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          namespace TEXT NOT NULL,
          session_id TEXT NOT NULL,
          agent_id TEXT NOT NULL,
          provider_session_id TEXT NOT NULL,
          cwd TEXT,
          locator_json TEXT,
          first_seen_at INTEGER NOT NULL,
          last_seen_at INTEGER NOT NULL,
          UNIQUE(namespace, session_id, agent_id, provider_session_id)
        );

CREATE TABLE kv_state (
          namespace TEXT NOT NULL,
          key TEXT NOT NULL,
          value TEXT NOT NULL,
          updated_at INTEGER NOT NULL,
          PRIMARY KEY(namespace, key)
        );

CREATE TABLE legacy_role_profile_archive (
          migration_version INTEGER NOT NULL,
          profile_id TEXT NOT NULL,
          role TEXT NOT NULL,
          profile_json TEXT NOT NULL,
          archived_at INTEGER NOT NULL,
          PRIMARY KEY (migration_version, profile_id)
        );

CREATE TABLE model_configs (
          id TEXT PRIMARY KEY,
          model_id TEXT,
          display_name TEXT NOT NULL,
          provider TEXT NOT NULL,
          is_enabled INTEGER NOT NULL DEFAULT 1,
          is_default INTEGER NOT NULL DEFAULT 0,
          config_json TEXT,
          updated_at INTEGER
        );

CREATE TABLE native_transcript_chunks (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          turn_row_id INTEGER NOT NULL REFERENCES native_transcript_turns(id) ON DELETE CASCADE,
          messages_json TEXT NOT NULL,
          entries_json TEXT NOT NULL
        );

CREATE TABLE native_transcript_leases (
          transcript_id TEXT PRIMARY KEY,
          writer_id TEXT NOT NULL,
          updated_at INTEGER NOT NULL
        );

CREATE TABLE native_transcript_turns (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          transcript_id TEXT NOT NULL,
          turn_id TEXT NOT NULL,
          status TEXT NOT NULL CHECK(status IN ('running', 'completed', 'failed', 'cancelled', 'interrupted')),
          messages_json TEXT NOT NULL DEFAULT '[]',
          entries_json TEXT NOT NULL DEFAULT '[]',
          usage_json TEXT,
          provider_json TEXT,
          error_message TEXT,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL, writer_id TEXT NOT NULL DEFAULT '', projection_seq INTEGER NOT NULL DEFAULT 0, loop_guard_json TEXT,
          UNIQUE(transcript_id, turn_id)
        );

CREATE TABLE prompt_queue (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      client_message_id TEXT NOT NULL UNIQUE,
      auth_user_id TEXT NOT NULL,
      user_id INTEGER NOT NULL,
      session_id TEXT NOT NULL,
      chat_session_id TEXT NOT NULL,
      history_key TEXT NOT NULL,
      logical_history_key TEXT NOT NULL,
      lane_namespace TEXT NOT NULL,
      lane_generation INTEGER NOT NULL CHECK(lane_generation >= 1),
      workspace_root TEXT NOT NULL,
      payload_json TEXT NOT NULL,
      payload_hash TEXT NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('queued', 'running', 'completed', 'failed')),
      attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts >= 0),
      last_error TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      started_at INTEGER,
      completed_at INTEGER,
      lease_owner TEXT,
      lease_expires_at INTEGER
    );

CREATE TABLE prompt_queue_cancellations (
      client_message_id TEXT PRIMARY KEY,
      auth_user_id TEXT NOT NULL,
      user_id INTEGER NOT NULL,
      session_id TEXT NOT NULL,
      chat_session_id TEXT NOT NULL,
      logical_history_key TEXT NOT NULL,
      lane_namespace TEXT NOT NULL,
      lane_generation INTEGER NOT NULL CHECK(lane_generation >= 1),
      cancelled_at INTEGER NOT NULL
    );

CREATE TABLE prompt_queue_ownership (
      id INTEGER PRIMARY KEY CHECK(id = 1),
      owner_id TEXT NOT NULL,
      owner_pid INTEGER NOT NULL CHECK(owner_pid > 0),
      lease_expires_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );

CREATE TABLE review_queue_leases (
          project_id TEXT PRIMARY KEY,
          owner_id TEXT NOT NULL,
          expires_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL
        );

CREATE TABLE reviewer_model_settings (
          id INTEGER PRIMARY KEY CHECK (id = 1),
          model_config_id TEXT,
          updated_at INTEGER NOT NULL
        );

CREATE TABLE role_profiles (
          id TEXT PRIMARY KEY,
          role TEXT NOT NULL UNIQUE CHECK (role IN ('acopilot', 'reviewer')),
          name TEXT NOT NULL,
          model_id TEXT NOT NULL,
          reasoning_effort TEXT NOT NULL DEFAULT 'high',
          system_prompt TEXT NOT NULL,
          is_enabled INTEGER NOT NULL DEFAULT 1,
          is_default INTEGER NOT NULL DEFAULT 0,
          version INTEGER NOT NULL DEFAULT 1,
          updated_at INTEGER NOT NULL
        );

CREATE TABLE schema_version (
      id INTEGER PRIMARY KEY CHECK (id = 1),
      version INTEGER NOT NULL DEFAULT 0,
      updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );

CREATE TABLE sync_events (
          seq INTEGER PRIMARY KEY AUTOINCREMENT,
          namespace TEXT NOT NULL,
          lane_key TEXT NOT NULL,
          event_type TEXT NOT NULL,
          event_id TEXT,
          revision INTEGER NOT NULL DEFAULT 1,
          payload TEXT NOT NULL,
          ts INTEGER NOT NULL,
          run_id TEXT
        );

CREATE TABLE sync_lane_state (
          namespace TEXT NOT NULL,
          lane_key TEXT NOT NULL,
          trimmed_through_seq INTEGER NOT NULL DEFAULT 0,
          PRIMARY KEY(namespace, lane_key)
        );

CREATE TABLE task_messages (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          task_id TEXT NOT NULL,
          namespace TEXT NOT NULL,
          session_id TEXT NOT NULL,
          role TEXT NOT NULL,
          kind TEXT,
          payload TEXT,
          ts INTEGER NOT NULL,
          FOREIGN KEY(task_id) REFERENCES tasks(task_id) ON DELETE CASCADE
        );

CREATE TABLE tasks (
          task_id TEXT NOT NULL PRIMARY KEY,
          parent_task_id TEXT,
          namespace TEXT NOT NULL,
          session_id TEXT NOT NULL,
          agent_id TEXT NOT NULL,
          revision INTEGER NOT NULL,
          status TEXT NOT NULL,
          spec_json TEXT NOT NULL,
          result_json TEXT,
          verification_json TEXT,
          attempts INTEGER NOT NULL DEFAULT 0,
          last_error TEXT,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL
        );

CREATE TABLE thread_state (
          namespace TEXT NOT NULL,
          user_hash TEXT NOT NULL,
          thread_id TEXT NOT NULL,
          cwd TEXT,
          updated_at INTEGER NOT NULL,
          PRIMARY KEY(namespace, user_hash)
        );

CREATE TABLE tool_call_metrics (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          workspace_id TEXT NOT NULL,
          session_id TEXT NOT NULL,
          tool_name TEXT NOT NULL,
          created_at INTEGER NOT NULL,
          status TEXT NOT NULL
        );

CREATE TABLE web_lane_generations (
          namespace TEXT NOT NULL,
          lane_key TEXT NOT NULL,
          generation INTEGER NOT NULL CHECK(generation >= 1),
          updated_at INTEGER NOT NULL,
          PRIMARY KEY(namespace, lane_key)
        );

CREATE TABLE web_push_subscriptions (
      endpoint TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      p256dh TEXT NOT NULL,
      auth TEXT NOT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );

CREATE TABLE web_sessions (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      token_hash TEXT NOT NULL UNIQUE,
      created_at INTEGER NOT NULL,
      expires_at INTEGER NOT NULL,
      revoked_at INTEGER,
      last_seen_at INTEGER,
      last_seen_ip TEXT,
      user_agent TEXT,
      FOREIGN KEY(user_id) REFERENCES web_users(id) ON DELETE CASCADE
    );

CREATE TABLE web_task_bundle_drafts (
          draft_id TEXT NOT NULL PRIMARY KEY,
          namespace TEXT NOT NULL,
          auth_user_id TEXT NOT NULL,
          workspace_root TEXT NOT NULL,
          request_id TEXT,
          source_chat_session_id TEXT NOT NULL,
          source_history_key TEXT,
          bundle_json TEXT NOT NULL,
          status TEXT NOT NULL,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL,
          approved_at INTEGER,
          approved_task_ids_json TEXT,
          last_error TEXT
        );

CREATE TABLE web_users (
      id TEXT PRIMARY KEY,
      username TEXT NOT NULL UNIQUE,
      password_hash TEXT NOT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      last_login_at INTEGER,
      disabled_at INTEGER
    );

CREATE INDEX idx_action_jobs_lookup ON action_jobs(project_id, status, created_at);

CREATE INDEX idx_action_jobs_review_head
            ON action_jobs(project_id, pr_number, head_sha, superseded_at);

CREATE INDEX idx_compaction_ws_ts
          ON compaction_snapshots(workspace_id, created_at DESC);

CREATE INDEX idx_global_rule_audit_rule
          ON global_rule_audit_log(rule_id, ts DESC);

CREATE INDEX idx_global_rule_audit_ts
          ON global_rule_audit_log(ts DESC);

CREATE INDEX idx_global_rules_enabled
          ON global_rules(enabled, priority, created_at);

CREATE UNIQUE INDEX idx_history_entries_client_message_id
          ON history_entries(
            namespace,
            session_id,
            substr(kind, length('client_message_id:') + 1, instr(kind || ';', ';') - length('client_message_id:') - 1)
          )
          WHERE kind LIKE 'client_message_id:%';

CREATE INDEX idx_history_entries_session
          ON history_entries(namespace, session_id, id);

CREATE INDEX idx_history_session_links_lookup
          ON history_session_links(namespace, session_id, agent_id, last_seen_at DESC);

CREATE INDEX idx_native_chunks_turn ON native_transcript_chunks(turn_row_id, id);

CREATE INDEX idx_native_transcript_turns_order
          ON native_transcript_turns(transcript_id, id);

CREATE INDEX idx_prompt_queue_active
      ON prompt_queue(status, id);

CREATE INDEX idx_prompt_queue_cancellations_scope
      ON prompt_queue_cancellations(auth_user_id, session_id, chat_session_id, logical_history_key);

CREATE INDEX idx_prompt_queue_lane_fifo
      ON prompt_queue(auth_user_id, session_id, chat_session_id, logical_history_key, lane_generation, status, id);

CREATE INDEX idx_role_profiles_role ON role_profiles(role, is_enabled);

CREATE UNIQUE INDEX idx_sync_events_dedup
          ON sync_events(namespace, lane_key, event_type, event_id, revision)
          WHERE event_id IS NOT NULL;

CREATE INDEX idx_sync_events_lane
          ON sync_events(namespace, lane_key, seq);

CREATE INDEX idx_task_messages_task
          ON task_messages(namespace, session_id, task_id, id);

CREATE INDEX idx_tasks_active
          ON tasks(namespace, session_id, status, updated_at);

CREATE INDEX idx_web_push_subscriptions_user
      ON web_push_subscriptions(user_id);

COMMIT;
